import * as T from './vendor/three.js';
const $=s=>document.querySelector(s);
export function createDayNight({scene,renderer,camera,sky,sun,ambient,windowMaterials,photoMaterials=[]}){
 let hour=16.5,running=true,uiClock=-1;
 // An analytic sky driven by the sun: zenith/horizon gradient, a warm glow on the sun's side, sun and moon halos, and the weather cloud layer lit by the sun. Near the horizon it fades to the fog colour, so distant terrain blends into it.
 const skyMaterial=new T.ShaderMaterial({side:T.BackSide,depthWrite:false,fog:false,uniforms:{weatherAmount:{value:0},weatherTint:{value:new T.Color('#a2afb5')},daylight:{value:1},sunDirection:{value:new T.Vector3(0,1,0)},sunColor:{value:new T.Color()},zenithColor:{value:new T.Color()},horizonColor:{value:new T.Color()},glowColor:{value:new T.Color()},glowAmount:{value:0},sunHalo:{value:1},moonHalo:{value:0},fogColor:{value:scene.fog.color},cloudMap:{value:null},cloudOffset:{value:new T.Vector2()},cloudCoverage:{value:0},cloudHeight:{value:850},cloudTint:{value:new T.Color()},cloudShadow:{value:new T.Color()}},vertexShader:`varying vec3 vDirection;void main(){vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,fragmentShader:`uniform float weatherAmount;uniform vec3 weatherTint;uniform float daylight;uniform vec3 sunDirection;uniform vec3 sunColor;uniform vec3 zenithColor;uniform vec3 horizonColor;uniform vec3 glowColor;uniform float glowAmount;uniform float sunHalo;uniform float moonHalo;uniform vec3 fogColor;uniform sampler2D cloudMap;uniform vec2 cloudOffset;uniform float cloudCoverage;uniform float cloudHeight;uniform vec3 cloudTint;uniform vec3 cloudShadow;varying vec3 vDirection;void main(){vec3 dir=normalize(vDirection);float up=max(dir.y,0.0);vec3 color=mix(horizonColor,zenithColor,pow(up,0.55));
vec2 across=normalize(dir.xz+vec2(1e-5)),sunAcross=normalize(sunDirection.xz+vec2(1e-5));float toward=max(0.0,dot(across,sunAcross));color=mix(color,glowColor,glowAmount*(0.25+0.75*toward*toward)*pow(1.0-up,5.0));
float mu=max(dot(dir,sunDirection),0.0);color+=sunColor*(pow(mu,10.0)*0.22+pow(mu,90.0)*0.35+pow(mu,900.0)*1.2)*sunHalo;
float moon=max(dot(dir,-sunDirection),0.0);color+=vec3(0.32,0.4,0.55)*(pow(moon,40.0)*0.18+pow(moon,600.0)*0.5)*moonHalo;
float t=(cloudHeight-cameraPosition.y)/dir.y;if(t>0.0&&dir.y>0.015){vec2 p=(cameraPosition.xz+dir.xz*t)/4000.0,uv=vec2(p.x,-p.y)+cloudOffset;float a=smoothstep(0.3,0.72,texture2D(cloudMap,uv).a),fine=texture2D(cloudMap,uv*3.1+vec2(0.31,0.17)).a,shape=a-(1.0-fine)*0.22,density=smoothstep(1.0-cloudCoverage,1.0-cloudCoverage+0.3,shape)*(1.0-smoothstep(5000.0,15000.0,t)),thick=smoothstep(0.55,1.0,shape);vec3 cloud=mix(cloudTint,cloudShadow,thick*0.6)+sunColor*pow(mu,5.0)*(1.0-thick)*0.5*sunHalo;color=mix(color,cloud,density*0.92);}
color=mix(color,weatherTint,weatherAmount);gl_FragColor=vec4(color,1.0);
#include <tonemapping_fragment>
gl_FragColor.rgb=mix(gl_FragColor.rgb,fogColor,1.0-smoothstep(-0.02,0.1,dir.y));
#include <colorspace_fragment>
}`});sky.material=skyMaterial;
 const moonLight=new T.DirectionalLight('#a9c9ff',.35);scene.add(moonLight);
 // Sky objects sit a fixed distance from the camera; placing their depth on the far plane lets terrain at any distance hide them.
 const atInfinity=material=>{material.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>','#include <project_vertex>\n\tgl_Position.z=gl_Position.w;')};return material}
 const sunDisc=new T.Mesh(new T.SphereGeometry(85,12,8),atInfinity(new T.MeshBasicMaterial({color:'#fff0c7',fog:false,toneMapped:false})));
 const moonDisc=new T.Mesh(new T.SphereGeometry(63,12,8),atInfinity(new T.MeshBasicMaterial({color:'#dce9ff',fog:false,toneMapped:false})));scene.add(sunDisc,moonDisc);
 const starPositions=[],starColors=[];let seed=1701;const random=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};for(let i=0;i<650;i++){let az=random()*Math.PI*2,y=.03+random()*.97,r=Math.sqrt(1-y*y);starPositions.push(Math.cos(az)*r*9200,y*9200,Math.sin(az)*r*9200);const b=.5+.5*random()**2,warm=random();starColors.push(b*(.9+warm*.1),b*(.92+warm*.04),b*(1-warm*.12))}const starGeometry=new T.BufferGeometry();starGeometry.setAttribute('position',new T.Float32BufferAttribute(starPositions,3));starGeometry.setAttribute('color',new T.Float32BufferAttribute(starColors,3));
 // Round, soft stars of varied brightness instead of uniform square points.
 const dot=document.createElement('canvas');dot.width=dot.height=32;const dc=dot.getContext('2d'),glow=dc.createRadialGradient(16,16,0,16,16,16);glow.addColorStop(0,'rgba(255,255,255,1)');glow.addColorStop(.25,'rgba(255,255,255,.85)');glow.addColorStop(1,'rgba(255,255,255,0)');dc.fillStyle=glow;dc.fillRect(0,0,32,32);
 const stars=new T.Points(starGeometry,atInfinity(new T.PointsMaterial({color:'#e6efff',map:new T.CanvasTexture(dot),vertexColors:true,size:3.2,sizeAttenuation:false,transparent:true,opacity:0,depthWrite:false,fog:false,toneMapped:false})));stars.renderOrder=-5;scene.add(stars);
 const slider=$('#time-slider'),toggle=$('#time-running'),readout=$('#time-value'),phase=$('#time-phase');
 function sync(){const minutes=Math.floor(hour*60)%1440;const label=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');readout.textContent=label;$('#game-clock').textContent=label+' · VALLEY TIME';slider.value=minutes;slider.setAttribute('aria-valuetext',label);phase.textContent=hour<5||hour>=20?'NIGHT':hour<8?'DAWN':hour<16.5?'DAYLIGHT':hour<18?'AFTERNOON':'DUSK';toggle.textContent=running?'Ⅱ':'▶';toggle.setAttribute('aria-label',running?'Pause time':'Resume time');toggle.setAttribute('aria-pressed',String(!running))}
 toggle.onclick=()=>{running=!running;sync()};slider.addEventListener('input',()=>{hour=Number(slider.value)/60;running=false;sync();update(0)});
 document.querySelectorAll('[data-hour]').forEach(button=>button.onclick=()=>{hour=Number(button.dataset.hour);sync();update(0)});
 function skip(){const phases=[5.5,12,18.5,23];hour=phases.find(h=>h>hour+.1)??phases[0];sync();update(0)}
 const C=hex=>new T.Color(hex),palette={zenithDay:C('#2f69b8'),zenithTwilight:C('#2a3a78'),zenithNight:C('#030817'),horizonDay:C('#b4d0e2'),horizonGolden:C('#e8d6bd'),horizonTwilight:C('#d79a86'),horizonNight:C('#070f22'),glowGolden:C('#ffcf95'),glowTwilight:C('#ff7e45'),sunHigh:C('#fff6e8'),sunGolden:C('#ffd08f'),sunLow:C('#ff8a4c'),cloudDay:C('#fbfbf8'),cloudGolden:C('#ffd9b0'),cloudTwilight:C('#e98a74'),cloudNight:C('#1b2436'),skyLightDay:C('#d4e6ff'),skyLightNight:C('#41598a'),groundLightDay:C('#9aa38c'),groundLightNight:C('#141f30')};
 // three.js applies fog after tone mapping (it sRGB-encodes the fog colour itself), so the fog colour is the tone-mapped horizon colour.
 function displayed(color,exposure,out){const k=exposure/.6,r=color.r*k,g=color.g*k,b=color.b*k,i=[.59719*r+.35458*g+.04823*b,.076*r+.90834*g+.01566*b,.0284*r+.13383*g+.83777*b].map(v=>(v*(v+.0245786)-.000090537)/(v*(.983729*v+.432951)+.238081)),o=[1.60475*i[0]-.53108*i[1]-.07367*i[2],-.10208*i[0]+1.10813*i[1]-.00605*i[2],-.00327*i[0]-.07276*i[1]+1.07602*i[2]].map(v=>Math.min(1,Math.max(0,v)));return out.setRGB(o[0],o[1],o[2],T.LinearSRGBColorSpace)}
 function update(dt,advance=true){if(running&&advance)hour=(hour+dt/30)%24;const angle=(hour-6)/24*Math.PI*2,altitude=Math.sin(angle),day=T.MathUtils.smoothstep(altitude,-.35,.3),night=1-T.MathUtils.smoothstep(altitude,-.4,.05),twilight=Math.exp(-Math.pow(altitude/.24,2));const golden=1-T.MathUtils.smoothstep(altitude,.05,.45),light=T.MathUtils.smoothstep(altitude,-.12,.2),glowing=Math.exp(-Math.pow(altitude/.2,2)),u=skyMaterial.uniforms;
const direction=new T.Vector3(Math.cos(angle),altitude,-.4).normalize();sun.position.copy(direction).multiplyScalar(1000);
// A stronger, warmer sun against a softer sky light gives shape to buildings and long golden mornings and evenings.
sun.intensity=2.6*T.MathUtils.smoothstep(altitude,-.02,.25);sun.color.copy(palette.sunHigh).lerp(palette.sunGolden,golden).lerp(palette.sunLow,glowing*.8);ambient.intensity=T.MathUtils.lerp(.22,1.3,day);ambient.color.copy(palette.skyLightNight).lerp(palette.skyLightDay,day);ambient.groundColor.copy(palette.groundLightNight).lerp(palette.groundLightDay,day);moonLight.position.copy(direction).multiplyScalar(-1000);moonLight.intensity=.45*night;
u.zenithColor.value.copy(palette.zenithNight).lerp(palette.zenithDay,light).lerp(palette.zenithTwilight,glowing*.45*(1-light*.6));u.horizonColor.value.copy(palette.horizonNight).lerp(palette.horizonDay,light).lerp(palette.horizonGolden,golden*light*.5).lerp(palette.horizonTwilight,glowing*.6);u.glowColor.value.copy(palette.glowGolden).lerp(palette.glowTwilight,glowing);u.glowAmount.value=Math.max(golden*light*.35,glowing*.85);u.sunColor.value.copy(sun.color);u.sunDirection.value.copy(direction);u.daylight.value=day;u.sunHalo.value=T.MathUtils.smoothstep(altitude,-.08,.02);u.moonHalo.value=night;u.cloudTint.value.copy(palette.cloudNight).lerp(palette.cloudDay,light).lerp(palette.cloudGolden,golden*light*.6).lerp(palette.cloudTwilight,glowing*.7);u.cloudShadow.value.copy(u.cloudTint.value).multiplyScalar(.62).lerp(u.zenithColor.value,.25);
renderer.toneMappingExposure=T.MathUtils.lerp(1.22,1.05,day);displayed(u.horizonColor.value,renderer.toneMappingExposure,scene.fog.color);scene.fog.near=T.MathUtils.lerp(300,800,day);sunDisc.position.copy(direction).multiplyScalar(8500).add(camera.position);sunDisc.visible=altitude>-.04;sunDisc.material.color.set('#fff2cc').lerp(new T.Color('#ffad70'),twilight);moonDisc.position.copy(direction).multiplyScalar(-8500).add(camera.position);moonDisc.visible=altitude<.04;stars.material.opacity=night*.85;stars.position.copy(camera.position);for(const material of windowMaterials)material.emissiveIntensity=night*(material.userData.nightBrightness??1.7);for(const material of photoMaterials)material.color.set('#101b32').lerp(new T.Color('#ffffff'),day);const now=Math.floor(hour*60);if(now!==uiClock){uiClock=now;sync()}return{night,day,hour}}
 update(0);return{update,skip};
}
